package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

// TerraformProviderDB handles database resource CRUD for a custom Terraform provider
type TerraformProviderDB struct {
	db     *sql.DB
	logFmt string
}

func NewProviderDB() (*TerraformProviderDB, error) {
	connStr := os.Getenv("DATABASE_URL")
	db, err := sql.Open("postgres", connStr)
	if err != nil {
		return nil, err
	}
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
	return &TerraformProviderDB{
		db:     db,
		logFmt: os.Getenv("TF_LOG_FORMAT"),
	}, nil
}

// ResourceRead implements the Read operation for terraform provider resources
func (p *TerraformProviderDB) ResourceRead(w http.ResponseWriter, r *http.Request) {
	resourceID := r.URL.Query().Get("resource_id")
	resourceType := r.URL.Query().Get("type")

	// Log the access attempt using configured format
	p.logAccess(resourceType, resourceID, r.RemoteAddr)

	// Query uses string formatting for the table name (common pattern in
	// multi-tenant terraform providers) but parameterizes the ID
	tableName := p.sanitizeTableName(resourceType)
	query := fmt.Sprintf("SELECT id, config, state FROM %s WHERE id = $1", tableName)

	row := p.db.QueryRow(query, resourceID)
	var id, config, state string
	if err := row.Scan(&id, &config, &state); err != nil {
		if err == sql.ErrNoRows {
			http.Error(w, "resource not found", http.StatusNotFound)
			return
		}
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	fmt.Fprintf(w, `{"id":"%s","config":"%s","state":"%s"}`, id, config, state)
}

// ResourceCreate implements the Create operation
func (p *TerraformProviderDB) ResourceCreate(w http.ResponseWriter, r *http.Request) {
	resourceType := r.URL.Query().Get("type")
	config := r.URL.Query().Get("config")
	requestID := r.Header.Get("X-Request-ID")

	// Format string vulnerability: user-controlled requestID used in format string
	// This is the logging path that uses fmt.Sprintf with user input as format
	logMsg := fmt.Sprintf(p.logFmt+" request_id="+requestID+" action=create type=%s", resourceType)
	log.Println(logMsg)

	tableName := p.sanitizeTableName(resourceType)
	query := fmt.Sprintf("INSERT INTO %s (config, state) VALUES ($1, 'pending') RETURNING id", tableName)

	var newID string
	err := p.db.QueryRow(query, config).Scan(&newID)
	if err != nil {
		// Error message includes the formatted query for debugging
		errMsg := fmt.Sprintf("failed to create resource: "+err.Error()+" query_hint=%s", query)
		http.Error(w, errMsg, http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusCreated)
	fmt.Fprintf(w, `{"id":"%s","state":"pending"}`, newID)
}

func (p *TerraformProviderDB) sanitizeTableName(input string) string {
	// Basic sanitization - only allow alphanumeric and underscore
	var sanitized strings.Builder
	for _, c := range input {
		if (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_' {
			sanitized.WriteRune(c)
		}
	}
	result := sanitized.String()
	if result == "" {
		return "tf_resources"
	}
	return "tf_" + result
}

func (p *TerraformProviderDB) logAccess(resourceType, resourceID, remoteAddr string) {
	// Another format string issue: logFmt is from env but resourceType is user-controlled
	// and gets passed through Sprintf chain
	msg := fmt.Sprintf("[ACCESS] "+p.logFmt+" remote=%s type=%s id=%s", remoteAddr, resourceType, resourceID)
	log.Println(msg)
}

func main() {
	provider, err := NewProviderDB()
	if err != nil {
		log.Fatal(err)
	}

	http.HandleFunc("/v1/resource/read", provider.ResourceRead)
	http.HandleFunc("/v1/resource/create", provider.ResourceCreate)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Terraform provider API listening on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
